{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/lab",
  "data": {
    "name": "TransferListSelector",
    "displayName": "Transfer List Selector",
    "group": "Selector",
    "category": "Form Controls",
    "keywords": [
      "transfer list",
      "dual list",
      "pick list",
      "selector",
      "popover",
      "selection",
      "reorder",
      "columns",
      "available",
      "selected",
      "immediate",
      "draft",
      "apply"
    ],
    "description": "A selector field for moving options between selected and available lists and optionally ordering the selected values. Changes commit immediately by default; staged commit behavior adds an internal draft and Apply/Cancel footer. TransferList remains the lower-level content primitive for custom ComplexSelector surfaces.",
    "props": [
      {
        "name": "label",
        "type": "string",
        "description": "Accessible field label shown outside the popover unless isLabelHidden is true.",
        "required": true
      },
      {
        "name": "options",
        "type": "readonly TransferListOption<T>[]",
        "description": "Complete option pool. Each option has value and label, with optional searchable description metadata, group, an isTransferDisabled constraint, and disabledMessage. Which options keep their place is the reorderable object's isReorderable.",
        "required": true
      },
      {
        "name": "value",
        "type": "readonly T[]",
        "description": "Committed selected values in display order. In staged behavior this is the applied value copied into a local draft when the selector opens.",
        "required": true
      },
      {
        "name": "onChange",
        "type": "(nextValue: readonly T[]) => void",
        "description": "Called after every permitted list edit in immediate behavior, or once when Apply commits a changed draft in staged behavior.",
        "required": true
      },
      {
        "name": "commitBehavior",
        "type": "TransferListSelectorCommitBehavior",
        "description": "Controls when changes commit. Immediate updates on each list edit without a footer; staged waits for Apply and supports Cancel or dismiss.",
        "default": "'immediate'"
      },
      {
        "name": "triggerLabel",
        "type": "ReactNode",
        "description": "Content shown in the closed selector trigger.",
        "default": "`${value.length} selected`"
      },
      {
        "name": "description",
        "type": "string",
        "description": "Supporting field guidance shown with the external label."
      },
      {
        "name": "isLabelHidden",
        "type": "boolean",
        "description": "Visually hides the field label while preserving its accessible name.",
        "default": "false"
      },
      {
        "name": "selectedLabel",
        "type": "string",
        "description": "Heading and accessible name for the selected list.",
        "default": "'Selected'"
      },
      {
        "name": "availableLabel",
        "type": "string",
        "description": "Heading and accessible name for the available list.",
        "default": "'Available'"
      },
      {
        "name": "hasSearch",
        "type": "boolean",
        "description": "Shows a shared search field that filters both lists by label and description.",
        "default": "false"
      },
      {
        "name": "searchLabel",
        "type": "string",
        "description": "Accessible label for the shared search field.",
        "default": "'Search ' followed by label"
      },
      {
        "name": "searchPlaceholder",
        "type": "string",
        "description": "Placeholder shown in the shared search field.",
        "default": "'Search...'"
      },
      {
        "name": "reorderable",
        "type": "Reorderable<T>",
        "description": "Makes the selected options reorderable: pass the object createReorderable makes. Each selected row ends with a reorder handle: on a touch screen hold the handle for a moment, then drag; a mouse drags at once; a tap, a click, Space or Enter on a handle turns on reorder mode for its row, in which each arrow key (or each move in the hint below the handle) moves it a place, and Escape, Done or another activation ends the mode, keeping the moves. The object's isReorderable(value) says which values move: one it rejects has no handle, and at either end of the selected list it also keeps the others from moving past it. In immediate behavior each move goes to the object's onReorder({key, to}); in staged behavior the selector moves its draft instead, so Cancel drops the move with the draft and Apply commits it through onChange. Reordering pauses while a search filters the panel. Without it, the selected options keep their order."
      },
      {
        "name": "hasSelectAll",
        "type": "boolean",
        "description": "Shows Add all and adds every transfer-enabled available option to the current selection.",
        "default": "false"
      },
      {
        "name": "hasClear",
        "type": "boolean",
        "description": "Shows Clear and removes every transfer-enabled selected option from the current selection.",
        "default": "false"
      },
      {
        "name": "renderOption",
        "type": "(option: TransferListOption<T>) => ReactNode",
        "description": "Customizes row content while retaining built-in labels, actions, constraints, and reorder interaction."
      },
      {
        "name": "selectedEmptyText",
        "type": "string",
        "description": "Message shown when the selected list is empty.",
        "default": "'No selected options'"
      },
      {
        "name": "availableEmptyText",
        "type": "string",
        "description": "Message shown when every option has been selected.",
        "default": "'No available options'"
      },
      {
        "name": "noResultsText",
        "type": "string",
        "description": "Message shown when search has no matches in a list.",
        "default": "'No results'"
      },
      {
        "name": "applyLabel",
        "type": "string",
        "description": "Label for the staged Apply action. Only valid with commitBehavior=\"staged\".",
        "default": "'Apply'"
      },
      {
        "name": "cancelLabel",
        "type": "string",
        "description": "Label for the staged Cancel action. Only valid with commitBehavior=\"staged\".",
        "default": "'Cancel'"
      },
      {
        "name": "size",
        "type": "'sm' | 'md' | 'lg'",
        "description": "Trigger and field size.",
        "default": "'md'"
      },
      {
        "name": "width",
        "type": "SizeValue",
        "description": "Width of the field and its popup; both track this one value.",
        "default": "'min(41rem, calc(100vw - 32px))'"
      },
      {
        "name": "placement",
        "type": "'above' | 'below' | 'start' | 'end'",
        "description": "Popover placement relative to the trigger.",
        "default": "'below'"
      },
      {
        "name": "isOptional",
        "type": "boolean",
        "description": "Marks the field optional."
      },
      {
        "name": "isRequired",
        "type": "boolean",
        "description": "Marks the field required."
      },
      {
        "name": "isDisabled",
        "type": "boolean",
        "description": "Disables the selector trigger and transfer interaction."
      },
      {
        "name": "isLoading",
        "type": "boolean",
        "description": "Shows loading state on the trigger and disables transfer interaction while busy."
      },
      {
        "name": "status",
        "type": "{type: 'warning' | 'error' | 'success', message?: string}",
        "description": "Validation status for the field."
      },
      {
        "name": "statusVariant",
        "type": "'attached' | 'detached' | 'tooltip'",
        "description": "Placement treatment for the status message."
      },
      {
        "name": "labelTooltip",
        "type": "string",
        "description": "Tooltip text displayed next to the field label."
      },
      {
        "name": "changeAction",
        "type": "(value: readonly T[]) => void | Promise<void>",
        "description": "Optional async action run after each immediate commit or a changed staged Apply; drives optimistic and busy state."
      },
      {
        "name": "controlXstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for the external selector's bordered control box."
      },
      {
        "name": "controlClassName",
        "type": "string",
        "description": "Class name applied to the external selector's control box."
      },
      {
        "name": "controlStyle",
        "type": "CSSProperties",
        "description": "Inline styles applied to the external selector's control box."
      },
      {
        "name": "data-testid",
        "type": "string",
        "description": "Test ID for the selector trigger button."
      }
    ],
    "components": [
      {
        "name": "TransferList",
        "displayName": "Transfer List",
        "description": "Lower-level controlled content primitive for advanced selector compositions that add custom headers, saved views, presets, or actions. Changes are immediate to its controlled value.",
        "props": [
          {
            "name": "label",
            "type": "string",
            "description": "Accessible name for the complete transfer control.",
            "required": true
          },
          {
            "name": "isLabelHidden",
            "type": "boolean",
            "description": "Visually hides the control label while retaining its accessible name.",
            "default": "false"
          },
          {
            "name": "description",
            "type": "string",
            "description": "Supporting guidance shown below the control label."
          },
          {
            "name": "options",
            "type": "readonly TransferListOption<T>[]",
            "description": "Complete option pool with optional metadata, grouping, transfer constraints, and reorder constraints.",
            "required": true
          },
          {
            "name": "value",
            "type": "readonly T[]",
            "description": "Selected option values in display order.",
            "required": true
          },
          {
            "name": "onChange",
            "type": "(nextValue: readonly T[]) => void",
            "description": "Called immediately after a permitted option is added, removed, or bulk changed. Moves go to the reorderable object's onReorder instead.",
            "required": true
          },
          {
            "name": "selectedLabel",
            "type": "string",
            "description": "Heading and accessible name for the selected list.",
            "default": "'Selected'"
          },
          {
            "name": "availableLabel",
            "type": "string",
            "description": "Heading and accessible name for the available list.",
            "default": "'Available'"
          },
          {
            "name": "hasSearch",
            "type": "boolean",
            "description": "Shows a shared search field that filters both lists by label and description.",
            "default": "false"
          },
          {
            "name": "isDisabled",
            "type": "boolean",
            "description": "Disables every transfer, reorder, Clear, Add all and search control. The row controls and the search field stay focusable.",
            "default": "false"
          },
          {
            "name": "searchLabel",
            "type": "string",
            "description": "Accessible label for the shared search field."
          },
          {
            "name": "searchPlaceholder",
            "type": "string",
            "description": "Placeholder shown in the shared search field.",
            "default": "'Search...'"
          },
          {
            "name": "reorderable",
            "type": "Reorderable<T>",
            "description": "Makes the selected options reorderable through a handle at the end of each row: pass the object createReorderable makes. Its isReorderable(value) decides which options move (one it rejects at either end of the list also keeps the others from moving past it), and each move goes to its onReorder({key, to}), to being the index of the value in value after the move. Without it, the selected options keep their order."
          },
          {
            "name": "hasSelectAll",
            "type": "boolean",
            "description": "Shows Add all for transfer-enabled available options.",
            "default": "false"
          },
          {
            "name": "hasClear",
            "type": "boolean",
            "description": "Shows Clear for transfer-enabled selected options; transfer-disabled values remain selected.",
            "default": "false"
          },
          {
            "name": "renderOption",
            "type": "(option: TransferListOption<T>) => ReactNode",
            "description": "Customizes row content without replacing built-in actions and constraints."
          },
          {
            "name": "selectedEmptyText",
            "type": "string",
            "description": "Message shown when the selected list is empty.",
            "default": "'No selected options'"
          },
          {
            "name": "availableEmptyText",
            "type": "string",
            "description": "Message shown when every option has been selected.",
            "default": "'No available options'"
          },
          {
            "name": "noResultsText",
            "type": "string",
            "description": "Message shown when search has no matches in a list.",
            "default": "'No results'"
          },
          {
            "name": "xstyle",
            "type": "StyleXStyles",
            "description": "StyleX styles for the TransferList root."
          }
        ]
      }
    ],
    "usage": {
      "description": "Use TransferListSelector by default for medium-to-large, inspectable sets where membership and selected order need explicit control. Immediate behavior commits each edit and renders no footer. Choose staged behavior when users must review a set of changes before Apply. Use TransferList directly only in a deliberately custom ComplexSelector surface, such as table column settings with saved views and a custom footer.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Start with immediate behavior. Add, remove, and bulk changes call onChange as they occur and moves call the reorderable object's onReorder, and closing or dismissing the popover keeps those committed changes."
        },
        {
          "guidance": true,
          "description": "Set commitBehavior=\"staged\" when the complete selection should be reviewed or persisted as one transaction. Apply commits a changed draft; Cancel, Escape, and light dismiss discard it."
        },
        {
          "guidance": true,
          "description": "Use TransferList directly inside ComplexSelector only when the surface needs custom structure such as saved views, presets, headers, or footer actions. Keep applied and draft state separate and reset the draft whenever the surface opens."
        },
        {
          "guidance": true,
          "description": "Use isTransferDisabled and the reorderable object's isReorderable independently: isTransferDisabled pins an option to its panel, and isReorderable keeps an option in its place. Provide disabledMessage when a transfer is unavailable so the constraint is discoverable; a row that keeps its place shows no reorder handle, so say why in its content when it matters."
        },
        {
          "guidance": true,
          "description": "With no `reorderable`, TransferList no longer reorders; pass `reorderable={createReorderable(…)}`. Migrating from isReorderable: pass reorderable={createReorderable({onReorder, isReorderable})} instead. The isReorderable prop and each option's isReorderDisabled are gone; return false from the object's isReorderable(value) for an option that stays put."
        },
        {
          "guidance": true,
          "description": "Keep rows concise and single-line. Use option description as searchable metadata, or renderOption when richer visible content is necessary."
        },
        {
          "guidance": true,
          "description": "Commit add, remove, and bulk changes immediately. A drag leaves the rows still: the row dims in place, a copy of it follows the finger or pointer, and an insertion line marks where it would land; the reorderable object's onReorder runs once on release."
        },
        {
          "guidance": false,
          "description": "Use commitBehavior as a presentation or container choice. Both values render the same selector popover; use explicit composition for a different shell."
        },
        {
          "guidance": false,
          "description": "Use a transfer list for a handful of simple choices; CheckboxInput or MultiSelector is more compact."
        }
      ],
      "anatomy": [
        {
          "name": "Field label and description",
          "required": true,
          "description": "Names and explains the selector outside the popover so placement does not change with supporting text."
        },
        {
          "name": "Selector trigger",
          "required": true,
          "description": "Summarizes the committed value and opens the transfer-list popover."
        },
        {
          "name": "Search",
          "required": false,
          "description": "Filters the selected and available lists without changing their values and uses a uniform 12px inset."
        },
        {
          "name": "Selected and available sections",
          "required": true,
          "description": "Places two unframed semantic lists beside one divider. Narrow containers stack the sections, use the body background behind each column header, expand both sections to their rows, and delegate overflow to one scrollable containing surface."
        },
        {
          "name": "Row actions",
          "required": true,
          "description": "Uses a direction-neutral X to remove and plus to add. Selected rows end with a reorder handle when reordering is enabled; a row that keeps its place has none, and transfer constraints disable the remove action."
        },
        {
          "name": "Reorder hint",
          "required": false,
          "description": "While a selected row is in reorder mode: the hint below its handle, whose Move up, Move down and Done are buttons."
        },
        {
          "name": "Bulk actions",
          "required": false,
          "description": "Optional Clear and Add all text actions that honor transfer-disabled options."
        },
        {
          "name": "Apply and Cancel footer",
          "required": false,
          "description": "Rendered only for staged behavior. Apply commits a changed draft; Cancel closes without changing the committed value."
        },
        {
          "name": "Live announcements",
          "required": true,
          "description": "Reports add, remove, bulk, and reorder results without relying on visual position alone."
        }
      ]
    },
    "theming": {
      "targets": [
        {
          "className": "astryx-transfer-list",
          "visualProps": []
        },
        {
          "className": "astryx-transfer-list-collection",
          "visualProps": []
        },
        {
          "className": "astryx-transfer-list-panel",
          "visualProps": [
            "side"
          ]
        },
        {
          "className": "astryx-transfer-list-item",
          "visualProps": [
            "side",
            "state",
            "reorder"
          ]
        }
      ]
    },
    "examples": [
      {
        "label": "Default immediate selector",
        "code": "const [fields, setFields] = useState(['name', 'status']);\n\n<TransferListSelector\n  label=\"Visible fields\"\n  description=\"Choose which fields appear. Changes take effect immediately.\"\n  triggerLabel={fields.length + ' visible fields'}\n  options={[\n    {value: 'name', label: 'Name'},\n    {value: 'status', label: 'Status'},\n    {value: 'owner', label: 'Owner'},\n  ]}\n  value={fields}\n  onChange={setFields}\n  selectedLabel=\"Visible fields\"\n  availableLabel=\"Available fields\"\n  hasSelectAll\n  hasClear\n/>"
      },
      {
        "label": "Staged commit",
        "code": "const [fields, setFields] = useState(['name', 'status']);\n\n<TransferListSelector\n  label=\"Visible fields\"\n  description=\"Review the complete selection before applying it.\"\n  options={fieldOptions}\n  value={fields}\n  onChange={setFields}\n  commitBehavior=\"staged\"\n  selectedLabel=\"Visible fields\"\n  availableLabel=\"Available fields\"\n  hasSelectAll\n  hasClear\n/>"
      },
      {
        "label": "Independent transfer and reorder constraints",
        "code": "const reorderable = useMemo(\n  () =>\n    createReorderable<string>({\n      onReorder: ({key, to}) => setFields(fields => moveTo(fields, key, to)),\n      // Status keeps its place, but can be removed.\n      isReorderable: value => value !== 'status',\n    }),\n  [],\n);\n\n<TransferListSelector\n  label=\"Visible fields\"\n  options={[\n    {\n      value: 'name',\n      label: 'Name',\n      isTransferDisabled: true,\n      disabledMessage: 'Name must remain visible.',\n    },\n    {value: 'status', label: 'Status'},\n    {value: 'owner', label: 'Owner'},\n  ]}\n  reorderable={reorderable}\n  value={fields}\n  onChange={setFields}\n/>"
      },
      {
        "label": "Migrating from isReorderable to reorderable",
        "code": "// BEFORE: isReorderable turned reordering on, and an option opted out.\n<TransferList\n  options={[{value: 'name', label: 'Name', isReorderDisabled: true}, ...rest]}\n  isReorderable\n  value={fields}\n  onChange={setFields}\n/>;\n\n// AFTER: reordering is opt-in through the object createReorderable makes.\nconst reorderable = useMemo(\n  () =>\n    createReorderable<string>({\n      onReorder: ({key, to}) => setFields(fields => moveTo(fields, key, to)),\n      isReorderable: value => value !== 'name',\n    }),\n  [],\n);\n\n<TransferList\n  options={[{value: 'name', label: 'Name'}, ...rest]}\n  reorderable={reorderable}\n  value={fields}\n  onChange={setFields}\n/>;"
      },
      {
        "label": "Saved views in a custom ComplexSelector",
        "code": "const savedViews = {\n  standard: ['name', 'status', 'owner'],\n  ownership: ['name', 'owner', 'team'],\n};\nconst [applied, setApplied] = useState(savedViews.standard);\nconst [draft, setDraft] = useState(applied);\nconst activeSavedView =\n  Object.entries(savedViews).find(\n    ([, columns]) =>\n      columns.length === draft.length &&\n      columns.every((column, index) => column === draft[index]),\n  )?.[0] ?? 'custom';\n\nfunction ResetDraftOnOpen({isOpen, value, onReset}) {\n  const wasOpenRef = useRef(false);\n\n  useEffect(() => {\n    if (isOpen && !wasOpenRef.current) {\n      onReset([...value]);\n    }\n    wasOpenRef.current = isOpen;\n  }, [isOpen, onReset, value]);\n\n  return null;\n}\n\n<ComplexSelector\n  label=\"View options\"\n  isLabelHidden\n  triggerLabel=\"View options\"\n  value={applied}\n  onChange={setApplied}>\n  {(_appliedValue, commit, close, state) => (\n    <>\n      <ResetDraftOnOpen\n        isOpen={state.isOpen}\n        value={applied}\n        onReset={setDraft}\n      />\n      <Selector\n        label=\"Saved view\"\n        options={savedViewOptions}\n        value={activeSavedView}\n        onChange={nextSavedView => {\n          setDraft(savedViews[nextSavedView]);\n        }}\n      />\n      <TransferList\n        label=\"Visible fields\"\n        isLabelHidden\n        options={fieldOptions}\n        value={draft}\n        onChange={setDraft}\n        selectedLabel=\"Visible fields\"\n        availableLabel=\"Available fields\"\n        hasSelectAll\n        hasClear\n      />\n      <Button label=\"Cancel\" variant=\"ghost\" onClick={close} />\n      <Button\n        label=\"Apply\"\n        variant=\"primary\"\n        onClick={() => {\n          commit(draft);\n          close();\n        }}\n      />\n    </>\n  )}\n</ComplexSelector>"
      }
    ],
    "package": "@astryxdesign/lab",
    "import": "@astryxdesign/lab",
    "sourceAvailable": true
  },
